90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OID: u8 = 0x06;
111	    const TAG_SEQUENCE: u8 = 0x30;
112	    const TAG_SET: u8 = 0x31;
113	    const TAG_UTC_TIME: u8 = 0x17;
114	    const TAG_GENERALIZED_TIME: u8 = 0x18;
115	
116	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
117	    /// length encodings and truncated data.
118	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
119	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
120	        if tag & 0x1F == 0x1F {
121	            return Err("multi-byte tags are not supported".to_string());
122	        }
123	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
124	        let (len, header_len) = match first_len {
125	            0x00..=0x7F => (first_len as usize, 2),
126	            0x80 => return Err("indefinite length is not valid DER".to_string()),
127	            0xFF => return Err("reserved length byte".to_string()),
128	            long => {
129	                let n = (long & 0x7F) as usize;
130	                if !(1..=4).contains(&n) {
131	                    return Err("length is too large".to_string());
132	                }
133	                let bytes = buf
134	                    .get(2..2 + n)
135	                    .ok_or_else(|| "truncated long length".to_string())?;
136	                if bytes[0] == 0 {
137	                    return Err("non-minimal length encoding".to_string());
138	                }
139	                let mut len = 0usize;
140	                for &b in bytes {
141	                    len = len
142	                        .checked_shl(8)
143	                        .and_then(|l| l.checked_add(b as usize))
144	                        .ok_or_else(|| "length overflow".to_string())?;
145	                }
146	                if len < 0x80 {
147	                    return Err("non-minimal length encoding".to_string());
148	                }
149	                (len, 2 + n)
150	            }
151	        };
152	        let total = header_len
153	            .checked_add(len)
154	            .filter(|&t| t <= buf.len())
155	            .ok_or_else(|| "truncated TLV content".to_string())?;
156	        Ok((
157	            Tlv {
158	                tag,
159	                content: &buf[header_len..total],
160	            },
161	            &buf[total..],
162	        ))
163	    }
164	
165	    fn read_tagged<'a>(
166	        buf: &'a [u8],
167	        tag: u8,
168	        what: &str,
169	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
170	        let (tlv, rest) = read_tlv(buf)?;
171	        if tlv.tag != tag {
172	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
173	        }
174	        Ok((tlv, rest))
175	    }
176	
177	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
178	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
179	        // signatureValue BIT STRING } — and nothing trailing.
180	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
181	        if !rest.is_empty() {
182	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
183	        }
184	
185	        let c = cert.content;
186	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
187	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
188	        let (sig_value, c) = read_tlv(c)?;
189	        if sig_value.tag != TAG_BIT_STRING {
190	            return Err("signature must be a BIT STRING".to_string());
191	        }
192	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
193	            return Err("invalid signature BIT STRING".to_string());
194	        }
195	        if !c.is_empty() {
196	            return Err("trailing data in Certificate".to_string());
197	        }
198	
199	        // TBSCertificate ::= SEQUENCE {
200	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
201	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
202	        let t = tbs.content;
203	        let (first, t2) = read_tlv(t)?;
204	        let t = if first.tag == 0xA0 {
205	            let (version, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
206	            if !vrest.is_empty() || version.content.len() != 1 || version.content[0] > 2 {
207	                return Err("invalid certificate version".to_string());
208	            }
209	            t2
210	        } else {
211	            t // No explicit version: v1 certificate.
212	        };
213	
214	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
215	        let t = t3;
216	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
217	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
218	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
219	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
220	        let (_spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
221	        // Remaining fields (issuerUniqueID, subjectUniqueID, extensions, ...)
222	        // are optional; they must still each be well-formed TLVs.
223	        while !t.is_empty() {
224	            let (_, rest) = read_tlv(t)?;
225	            t = rest;
226	        }
227	
228	        let serial_hex = format_serial(serial.content)?;
229	        let issuer = format_name(issuer)?;
230	        let subject = format_name(subject)?;
231	
232	        let v = validity.content;
233	        let (nb, v2) = read_tlv(v)?;
234	        let (na, v3) = read_tlv(v2)?;
235	        if !v3.is_empty() {
236	            return Err("trailing data in validity".to_string());
237	        }
238	        let not_before = format_time(nb)?;
239	        let not_after = format_time(na)?;
240	
241	        Ok(Cert {
242	            subject,
243	            issuer,
244	            serial_hex,
245	            not_before,
246	            not_after,
247	        })
248	    }
249	
250	    /// Render the serial number as upper-case hex, matching the integer value
251	    /// (a DER sign-padding 0x00 byte is not part of the number).
252	    fn format_serial(content: &[u8]) -> Result<String, String> {
253	        if content.is_empty() {
254	            return Err("empty serial number".to_string());
255	        }
256	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
257	            return Err("non-minimal serial number encoding".to_string());
258	        }
259	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
260	            return Err("non-minimal serial number encoding".to_string());
261	        }
262	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
263	            return Err("negative serial number".to_string());
264	        }
265	        let digits = if content.len() > 1 && content[0] == 0x00 {
266	            &content[1..]
267	        } else {
268	            content
269	        };
270	        let mut s = String::with_capacity(digits.len() * 2);
271	        for b in digits {
272	            write!(s, "{b:02X}").unwrap();
273	        }
274	        if s.is_empty() {
275	            s.push_str("00");
276	        }
277	        Ok(s)
278	    }
279	
280	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
281	    /// multi-valued RDNs joined with '+'). Values are emitted as real UTF-8
282	    /// text so non-ASCII content is preserved verbatim.
283	    fn format_name(name: Tlv) -> Result<String, String> {
284	        let mut rdn_buf = name.content;
285	        let mut rdns: Vec<String> = Vec::new();
286	        while !rdn_buf.is_empty() {
287	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
288	            rdn_buf = rest;
289	
290	            let mut atv_buf = set.content;
291	            let mut parts = Vec::new();
292	            while !atv_buf.is_empty() {
293	                let (atv, rest) =
294	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
295	                atv_buf = rest;
296	
297	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
298	                let (value, after_value) = read_tlv(after_oid)?;
299	                if !after_value.is_empty() {
300	                    return Err("trailing data in attribute value".to_string());
301	                }
302	
303	                let oid_arcs = parse_oid(oid.content)?;
304	                let label = oid_short_name(&oid_arcs)
305	                    .map(str::to_string)
306	                    .unwrap_or_else(|| arcs_to_string(&oid_arcs));
307	                let text = decode_attribute_value(value.tag, value.content)?;
308	                parts.push(format!("{label}={}", escape_value(&text)));
309	            }
310	            if parts.is_empty() {
311	                return Err("empty RelativeDistinguishedName".to_string());
312	            }
313	            rdns.push(parts.join("+"));
314	        }
315	        rdns.reverse();
316	        Ok(rdns.join(","))
317	    }
318	
319	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
320	        if content.is_empty() {
321	            return Err("empty OID".to_string());
322	        }
323	        let mut arcs = Vec::new();
324	        let first = content[0];
325	        match first {
326	            0..=39 => {
327	                arcs.push(0);
328	                arcs.push(first as u64);
329	            }
330	            40..=79 => {
331	                arcs.push(1);
332	                arcs.push(first as u64 - 40);
333	            }
334	            _ => {
335	                arcs.push(2);
336	                arcs.push(first as u64 - 80);
337	            }
338	        }
339	        let mut i = 1;
340	        while i < content.len() {
341	            let mut value = 0u64;
342	            let start = i;
343	            loop {
344	                let b = content[i];
345	                value = value
346	                    .checked_mul(128)
347	                    .and_then(|v| v.checked_add((b & 0x7F) as u64))
348	                    .ok_or_else(|| "OID arc overflow".to_string())?;
349	                i += 1;
350	                if b & 0x80 == 0 {
351	                    break;
352	                }
353	                if i >= content.len() {
354	                    return Err("truncated OID arc".to_string());
355	                }
356	            }
357	            if i - start > 1 && content[start] == 0x80 {
358	                return Err("non-minimal OID arc encoding".to_string());
359	            }
360	            arcs.push(value);
361	        }
362	        Ok(arcs)
363	    }
364	
365	    fn arcs_to_string(arcs: &[u64]) -> String {
366	        arcs.iter()
367	            .map(u64::to_string)
368	            .collect::<Vec<_>>()
369	            .join(".")
370	    }
371	
372	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
373	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
374	        let name = match arcs {
375	            [2, 5, 4, 3] => "CN",
376	            [2, 5, 4, 4] => "SN",
377	            [2, 5, 4, 5] => "serialNumber",
378	            [2, 5, 4, 6] => "C",
379	            [2, 5, 4, 7] => "L",
380	            [2, 5, 4, 8] => "ST",
381	            [2, 5, 4, 9] => "STREET",
382	            [2, 5, 4, 10] => "O",
383	            [2, 5, 4, 11] => "OU",
384	            [2, 5, 4, 12] => "title",
385	            [2, 5, 4, 17] => "postalAddress",
386	            [2, 5, 4, 18] => "postalCode",
387	            [2, 5, 4, 20] => "telephoneNumber",
388	            [2, 5, 4, 42] => "givenName",
389	            [2, 5, 4, 43] => "initials",
390	            [2, 5, 4, 44] => "generationQualifier",
391	            [2, 5, 4, 46] => "dnQualifier",
392	            [2, 5, 4, 65] => "pseudonym",
393	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
394	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
395	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
396	            _ => return None,
397	        };
398	        Some(name)
399	    }
400	
401	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
402	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
403	        let s = match tag {
404	            0x0C => std::str::from_utf8(content)
405	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
406	                .to_string(),
407	            // ASCII-family strings: every byte is also its Unicode code point.
408	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
409	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
410	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
411	            0x1E => {
412	                if content.len() % 2 != 0 {
413	                    return Err("odd-length BMPString".to_string());
414	                }
415	                let units: Vec<u16> = content
416	                    .chunks_exact(2)
417	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
418	                    .collect();
419	                char::decode_utf16(units.iter().copied())
420	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
421	                    .collect::<Result<String, _>>()?
422	            }
423	            0x1C => {
424	                if content.len() % 4 != 0 {
425	                    return Err("invalid UniversalString length".to_string());
426	                }
427	                let mut s = String::new();
428	                for c in content.chunks_exact(4) {
429	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
430	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
431	                        return Err("invalid code point in UniversalString".to_string());
432	                    }
433	                    s.push(char::from_u32(cp).unwrap());
434	                }
435	                s
436	            }
437	            _ => {
438	                return Err(format!(
439	                    "unsupported attribute value string type (tag 0x{tag:02X})"
440	                ))
441	            }
442	        };
443	        Ok(s)
444	    }
445	
446	    /// RFC 4514 value escaping; everything above the ASCII control range
447	    /// (including CJK text) passes through unchanged.
448	    fn escape_value(value: &str) -> String {
449	        let mut out = String::with_capacity(value.len());
450	        let last = value.chars().count().saturating_sub(1);
451	        for (i, c) in value.chars().enumerate() {
452	            let at_edge = i == 0 || i == last;
453	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
454	                || (at_edge && (c == ' ' || c == '#'));
455	            if needs_backslash {
456	                out.push('\\');
457	                out.push(c);
458	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
459	                let mut buf = [0u8; 4];
460	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
461	                write!(out, "\\{b:02X}").unwrap();
462	            } else {
463	                out.push(c);
464	            }
465	        }
466	        out
467	    }
468	
469	    fn format_time(tlv: Tlv) -> Result<String, String> {
470	        let (y, mo, d, h, mi, se) = match tlv.tag {
471	            TAG_UTC_TIME => {
472	                let c = tlv.content;
473	                if c.len() != 13 || c[12] != b'Z' {
474	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
475	                }
476	                let digits = &c[..12];
477	                if !digits.iter().all(|b| b.is_ascii_digit()) {
478	                    return Err("non-numeric UTCTime".to_string());
479	                }
480	                let n = |a: usize, b: usize| -> u32 {
481	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
482	                };
483	                let yy = n(0, 1);
484	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
485	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
486	            }
487	            TAG_GENERALIZED_TIME => {
488	                let c = tlv.content;
489	                if c.len() != 15 || c[14] != b'Z' {
490	                    return Err(
491	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
492	                    );
493	                }
494	                let digits = &c[..14];
495	                if !digits.iter().all(|b| b.is_ascii_digit()) {
496	                    return Err("non-numeric GeneralizedTime".to_string());
497	                }
498	                let n = |a: usize, b: usize| -> u32 {
499	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
500	                };
501	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
502	            }
503	            other => return Err(format!("invalid time tag 0x{other:02X}")),
504	        };
505	        validate_datetime(y, mo, d, h, mi, se)?;
506	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
507	    }
508	
509	    fn validate_datetime(
510	        year: i32,
511	        month: u32,
512	        day: u32,
513	        hour: u32,
514	        minute: u32,
515	        second: u32,
516	    ) -> Result<(), String> {
517	        if !(1..=12).contains(&month) {
518	            return Err("invalid month in certificate time".to_string());
519	        }
520	        if hour > 23 || minute > 59 || second > 59 {
521	            return Err("invalid time of day in certificate time".to_string());
522	        }
523	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
524	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
525	        if day < 1 || day > days[(month - 1) as usize] {
526	            return Err("invalid day in certificate time".to_string());
527	        }
528	        Ok(())
529	    }
530	}
