    let start = *i;
    let mut value = 0u64;
    loop {
        let b = *content
            .get(*i)
            .ok_or_else(|| "truncated OID arc".to_string())?;
        value = value
            .checked_mul(128)
            .and_then(|v| v.checked_add((b & 0x7F) as u64))
            .ok_or_else(|| "OID arc overflow".to_string())?;
        *i += 1;
        if b & 0x80 == 0 {
            break;
        }
    }
    if *i - start > 1 && content[start] == 0x80 {
        return Err("non-minimal OID arc encoding".to_string());
    }
    Ok(value)
}

