INT = lambda c: T(0x02, c)
NULL = b"\x05\x00"
UTCT = lambda s: T(0x17, s.encode())
BITST = lambda c: T(0x03, b"\x00" + c)
UTF8 = lambda s: T(0x0C, s.encode())
PRT = lambda s: T(0x13, s.encode())

SHA256 = bytes.fromhex("608648016503040201")  # 2.16.840.1.101.3.4.2.1


def enc_arc(v):
    out = [v & 0x7F]
    v >>= 7
    while v:
