cases["common"] = cert(
    [[atv(CN, UTF8("example.com"))], [atv(O, UTF8("示例公司"))], [atv(C, PRT("CN"))]],
    [[atv(CN, UTF8("Example CA"))], [atv(O, UTF8("示例公司"))], [atv(C, PRT("CN"))]],
)

# 6. later-arc non-minimal still rejected
cases["nonminimal_later_arc"] = cert(
    [[atv(CN, PRT("ok"))]],
    None,
    raw_iss=name([[atv_raw_oid(b"\x55\x80\x04\x03", PRT("bad"))]]),
)

# 7. edge-space escaping with unknown OID value
cases["escaping"] = cert(
    [[atv(UNKNOWN, UTF8(" leading and trailing "))], [atv(CN, UTF8("x"))]],
    [[atv(CN, PRT("root"))]],
)

for name_, der in cases.items():
    with open(f"/tmp/{name_}.der", "wb") as f:
        f.write(der)
    print(name_, len(der))

